-- MySQL seed file for AgenticDataIngestion test fixtures (P18).
-- Idempotent: re-running this file is safe.
--   * CREATE TABLE IF NOT EXISTS guards table creation.
--   * INSERT ... ON DUPLICATE KEY UPDATE id = id makes every row a no-op on re-run.
-- Every statement is terminated by a single semicolon so the seeding lambda's
-- naive _split_statements helper can split on the semicolon and execute each
-- fragment in turn. No comment line in this file contains a semicolon, so the
-- naive split is safe.
--
-- Schema: 5-column customers + 6-column orders with a customer_id FK.
-- Volume: 50 customers (id 1..50), 150 orders (id 1..150, 3 per customer).
-- Timestamp anchor: 2025-01-31 (matches the "early 2025" framing in the task notes).

CREATE TABLE IF NOT EXISTS customers (
  id INT NOT NULL PRIMARY KEY,
  email VARCHAR(255) NOT NULL UNIQUE,
  name VARCHAR(255) NOT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  region VARCHAR(64) NOT NULL
);

CREATE TABLE IF NOT EXISTS orders (
  id INT NOT NULL PRIMARY KEY,
  customer_id INT NOT NULL,
  order_date TIMESTAMP NOT NULL,
  total_amount DECIMAL(10,2) NOT NULL,
  status VARCHAR(32) NOT NULL,
  CONSTRAINT fk_orders_customer FOREIGN KEY (customer_id) REFERENCES customers(id)
);

-- 50 customers (id 1..50). Distinct emails. Regions cycle through
-- {us-west, us-east, eu-west, ap-south}. created_at spans the prior 365 days.
ON DUPLICATE KEY UPDATE id = id;

-- 150 orders (id 1..150). customer_id cycles 1..50. status cycles through
-- {pending, shipped, delivered, cancelled}. order_date spans the prior 90 days.
-- total_amount in [10.00, 500.00].
ON DUPLICATE KEY UPDATE id = id;

